using namespace std;

using i64 = long long;
using pii = pair<int, int>;
using pll = pair<i64, i64>;

i64 mod_exp(i64 base, i64 exp, i64 mod) {
    i64 result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result % mod;
}

const i64 MOD = 1000000007;
const int MAX_SIZE = 30005;

