    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string text;
    cin >> text;

    string result;
    bool at_done = false;
    int len = text.length();

    for (int pos = 0; pos < len; ++pos) {
        if (pos > 0 && pos + 2 < len) {
            if (text[pos] == 'd' && text[pos+1] == 'o' && text[pos+2] == 't') {
                result.push_back('.');
                pos += 2;
                continue;
            }
        }

        if (!at_done && pos > 0 && pos + 1 < len) {
            if (text[pos] == 'a' && text[pos+1] == 't') {
                result.push_back('@');
                pos += 1;
                at_done = true;
                continue;
            }
        }

        result.push_back(text[pos]);
    }

    cout << result << '\n';
